#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int low, high;
} Interval;

int cmp(const void *a, const void *b) {
    Interval *ia = (Interval *)a;
    Interval *ib = (Interval *)b;
    if (ia->low != ib->low) return ia->low - ib->low;
    return ia->high - ib->high;
}

