}

int main() {
    int t;
    scanf("%d", &t);

    while (t--) {
        int n;
        scanf("%d", &n);

        int floors[200000]; // worst-case size
        int count = 0;

        for (int i = 0; i < n; i++) {
            int low, high;
            scanf("%d %d", &low, &high);
            for (int f = low; f <= high; f++) {
                floors[count++] = f;
            }
        }

        qsort(floors, count, sizeof(int), compare);

        int distinct = 0;
        for (int i = 0; i < count; i++) {
            if (i == 0 || floors[i] != floors[i-1]) {
                distinct++;
            }
        }

        printf("%d\n", distinct);
    }

    return 0;
}

