} Interval;

int cmp_interval(const void *a, const void *b) {
    const Interval *x = (const Interval *)a;
    const Interval *y = (const Interval *)b;
    if (x->l != y->l) return x->l - y->l;
    return x->r - y->r;
}

int main(void) {
