    while (scanf("%d", &n) == 1 && n != 0) {
        Interval *arr = (Interval *)malloc(sizeof(Interval) * n);
        if (!arr) return 0;

        for (int i = 0; i < n; i++) {
            scanf("%d %d", &arr[i].l, &arr[i].r);
            if (arr[i].l > arr[i].r) {
                int t = arr[i].l;
                arr[i].l = arr[i].r;
                arr[i].r = t;
            }
        }

        qsort(arr, n, sizeof(Interval), cmp_interval);

        long long total = 0;
        int curL = arr[0].l, curR = arr[0].r;

        for (int i = 1; i < n; i++) {
            if (arr[i].l > curR + 1) {
                total += (long long)curR - curL + 1;
                curL = arr[i].l;
                curR = arr[i].r;
