/*
We are given multiple datasets. In each dataset, several elevators can display
all floor numbers in their inclusive interval [low, high].

We need the count of distinct numbers that can appear on the display, i.e.
the size of the union of all intervals.

Assumed input format:
- Repeated datasets
- Each dataset starts with n
- Then n lines follow, each with low high
- A dataset with n = 0 ends input

This is the standard way to solve such interval-union counting problems.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n && n != 0) {
        vector<pair<long long, long long>> segs;
        segs.reserve(n);

        for (int i = 0; i < n; ++i) {
            long long l, r;
            cin >> l >> r;
            if (l > r) swap(l, r);
            segs.push_back({l, r});
        }

        sort(segs.begin(), segs.end());

        long long ans = 0;
        long long curL = segs[0].first, curR = segs[0].second;

        for (int i = 1; i < n; ++i) {
            long long l = segs[i].first, r = segs[i].second;

            // Since floors are integers, touching intervals like [1,3] and [4,5]
            // together cover 1..5 continuously in terms of displayed integers.
            if (l <= curR + 1) {
                curR = max(curR, r);
            } else {
                ans += curR - curL + 1;
                curL = l;
                curR = r;
            }
        }
        ans += curR - curL + 1;

        cout << ans << '\n';
    }

    return 0;
}

