public class ElevatorDisplay {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;

            List<int[]> intervals = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int low = sc.nextInt();
                int high = sc.nextInt();
                intervals.add(new int[]{low, high});
            }

            // Sort intervals by starting floor
            intervals.sort(Comparator.comparingInt(a -> a[0]));

            int totalFloors = 0;
            int currentStart = intervals.get(0)[0];
            int currentEnd = intervals.get(0)[1];

            for (int i = 1; i < intervals.size(); i++) {
                int start = intervals.get(i)[0];
                int end = intervals.get(i)[1];

                if (start <= currentEnd) {
                    // Overlapping intervals, merge
                    currentEnd = Math.max(currentEnd, end);
                } else {
                    // Non-overlapping, add previous range
                    totalFloors += (currentEnd - currentStart + 1);
                    currentStart = start;
                    currentEnd = end;
                }
            }
            // Add last range
            totalFloors += (currentEnd - currentStart + 1);

            System.out.println(totalFloors);
        }
        sc.close();
    }
}

