public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n;
            try {
                n = fs.nextInt();
            } catch (Exception e) {
                break;
            }

            if (n == 0) break;

            List<int[]> intervals = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int low = fs.nextInt();
                int high = fs.nextInt();
                if (low > high) {
                    int t = low;
                    low = high;
                    high = t;
                }
                intervals.add(new int[]{low, high});
            }

            intervals.sort(Comparator.comparingInt(a -> a[0]));

            long total = 0;
            int curL = intervals.get(0)[0];
            int curR = intervals.get(0)[1];

            for (int i = 1; i < intervals.size(); i++) {
                int l = intervals.get(i)[0];
                int r = intervals.get(i)[1];

                if (l > curR + 1) {
                    total += (long) curR - curL + 1;
                    curL = l;
                    curR = r;
                } else {
                    curR = Math.max(curR, r);
                }
            }
            total += (long) curR - curL + 1;

            out.append(total).append('\n');
        }

        System.out.print(out.toString());
    }
}

