import sys

def solve(data: str):
    nums = list(map(int, data.split()))
    if not nums:
        return ""

    out = []
    i = 0

    # Handle either:
    # 1) first number = number of test cases
    # 2) repeated datasets until EOF, each starting with n
    def parse_from(start, use_t):
        idx = start
        res = []
        if use_t:
            if idx >= len(nums):
                return None
            t = nums[idx]
            idx += 1
            for _ in range(t):
                if idx >= len(nums):
                    return None
                n = nums[idx]
                idx += 1
                intervals = []
                for _ in range(n):
                    if idx + 1 >= len(nums):
                        return None
                    a, b = nums[idx], nums[idx + 1]
                    idx += 2
                    if a > b:
                        a, b = b, a
                    intervals.append((a, b))
                res.append(intervals)
            if idx != len(nums):
                return None
            return res
        else:
            while idx < len(nums):
                n = nums[idx]
                idx += 1
                intervals = []
                for _ in range(n):
                    if idx + 1 >= len(nums):
                        return None
                    a, b = nums[idx], nums[idx + 1]
                    idx += 2
                    if a > b:
                        a, b = b, a
                    intervals.append((a, b))
                res.append(intervals)
            return res

    datasets = parse_from(0, True)
    if datasets is None:
        datasets = parse_from(0, False)

    for intervals in datasets:
        if not intervals:
            out.append("0")
            continue

        intervals.sort()
        total = 0
        cur_l, cur_r = intervals[0]

        for l, r in intervals[1:]:
            if l > cur_r + 1:
                total += cur_r - cur_l + 1
                cur_l, cur_r = l, r
            else:
                if r > cur_r:
                    cur_r = r

        total += cur_r - cur_l + 1
        out.append(str(total))

    return "\n".join(out)

